def sum_of_digits(numbers):
    def compute_sum(num):
        # Ensure the input is a positive integer
        if isinstance(num, int) and num >= 0:
            return sum(int(digit) for digit in str(num))
        return 0

    def flatten_list(lst):
        # Helper function to flatten nested lists
        for item in lst:
            if isinstance(item, list):
                yield from flatten_list(item)
            else:
                yield item

    # Flatten the input list and compute the sum of digits for valid numbers
    flattened_numbers = flatten_list(numbers)
    return sum(compute_sum(item) for item in flattened_numbers)

# Example usage and tests
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([10, 20, 4, 5, 'b', 70, 'a']) == 19
assert sum_of_digits([123, 456, -789, 0, 'test', [1, 2], None]) == 21
assert sum_of_digits([[10, 20, 4, 5, 'b', 70, 'a']]) == 19
